-- Blackwing Lair: the Classic armor, shields and cloaks that drop there had no item row (the WoW Forever client
-- blanks them), so every one of them was an invalid loot item and nothing dropped. 75 rows: Wowhead Classic
-- stats as budget shares, armor from the item level formula (matches Classic), Classic sell prices, Classic
-- equip spells as item effects, hotfix_data so the client shows them.
-- Also: sell prices for the 20 Molten Core tier 1 pieces 16849-16868 that went out with 0 in 2026_11_21_85.
DELETE FROM `item_sparse` WHERE `ID` IN (16818,16832,16898,16899,16902,16903,16904,16906,16907,16910,16911,16912,16913,16917,16918,16919,16920,16924,16925,16926,16927,16928,16932,16933,16934,16935,16936,16937,16940,16941,16943,16944,16945,16948,16949,16951,16952,16953,16956,16957,16959,16960,16961,16964,16965,19348,19349,19369,19370,19372,19373,19374,19385,19386,19387,19388,19389,19390,19391,19393,19394,19396,19398,19399,19400,19401,19402,19405,19407,19430,19433,19436,19437,19438,19439);
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900413 AND 9900506;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900413 AND 9900506;
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26112457 AND 26112719;
